This Terraform configuration creates a valid AWS Route 53 private hosted zone and associates it with a VPC using an `aws_route53_zone_association` resource. It includes a VPC, a private Route 53 hosted zone, and the zone association. A random suffix is used to avoid naming conflicts.

```hcl
terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "random_id" "suffix" {
  byte_length = 4
}

resource "aws_vpc" "example" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "route53-association-vpc-${random_id.suffix.hex}"
  }
}

resource "aws_route53_zone" "private" {
  name = "example-${random_id.suffix.hex}.internal"

  vpc {
    vpc_id = aws_vpc.example.id
  }

